import { useProgress } from "@react-three/drei";
import { useEffect, useState } from "react";
// ...other imports

function Home() {
  const [isLoaded, setIsLoaded] = useState(false);
  const isMobile = useIsMobile();
  const { active, progress } = useProgress();

  useEffect(() => {
    if (progress === 100 && !active) {
      setIsLoaded(true);
    }
  }, [progress, active]);

  // ...gsap useEffect unchanged

  return (
    <>
      {!isLoaded && (
        <div className="loading-screen">
          {/* loading content */}
        </div>
      )}

      <Navbar className={`${!isLoaded ? "hidden" : ""}`} />

      <main className={`main ${!isLoaded ? "hidden" : ""}`}>
        <Hero className="hero-section" />
        <About className="about-section" />
        <Projects className="projects-section" />
      </main>

      <Footer className={`footer-section ${!isLoaded ? "hidden" : ""}`} />
      <ScrollIndicator className={`scroll-indicator ${!isLoaded ? "hidden" : ""}`}>
        {/* ... */}
      </ScrollIndicator>
    </>
  );
}

export default Home;
